<script>
(() => {
    const modal = document.getElementById('admin-impact-modal');
    if (!modal) return;
    const issuedDate = modal.querySelector('#cert-issued');
    const expiryDate = modal.querySelector('#cert-expires');
    const syncExpiryMinimum = () => { if (issuedDate && expiryDate) expiryDate.min = issuedDate.value || ''; };
    if (issuedDate && expiryDate) {
        syncExpiryMinimum();
        issuedDate.addEventListener('change', syncExpiryMinimum);
    }
    document.querySelectorAll('[data-open-impact-modal]').forEach(button => button.addEventListener('click', () => modal.showModal()));
    document.querySelectorAll('[data-close-impact-modal]').forEach(button => button.addEventListener('click', () => modal.close()));
    modal.addEventListener('click', event => { if (event.target === modal) modal.close(); });
    modal.showModal();
    const url = new URL(window.location.href);
    if (url.searchParams.has('modal')) {
        url.searchParams.delete('modal');
        window.history.replaceState({}, '', url);
    }
})();
</script>
@endif
@include('traceability.partials.csv-import-dialog')
@endsection
